import { useState } from "react";

export default function PaginatedList({ items, pageSize = 5 }) {
  const [page, setPage] = useState(1);
  const totalPages = Math.ceil(items.length / pageSize);
  const current = totalPages === 0 ? 0 : Math.min(Math.max(page, 1), totalPages);
  const start = (Math.max(current, 1) - 1) * pageSize;
  const visible = items.slice(start, start + pageSize);

  return (
    <div>
      {items.length === 0 ? (
        <p>No items found</p>
      ) : (
        <ul>
          {visible.map((item, i) => (
            <li key={start + i}>{item}</li>
          ))}
        </ul>
      )}
      <button onClick={() => setPage(current - 1)} disabled={current <= 1}>Prev</button>
      <span data-testid="page-info">Page {current} of {totalPages}</span>
      <button onClick={() => setPage(current + 1)} disabled={current >= totalPages}>Next</button>
    </div>
  );
}

