import { test, afterEach } from "node:test";
import assert from "node:assert/strict";
import { render, screen, fireEvent, cleanup } from "@testing-library/react";
import PaginatedList from "../../src/PaginatedList.jsx";

afterEach(cleanup);

const items = (n) => Array.from({ length: n }, (_, i) => `Item ${i + 1}`);
const shown = () => Array.from(document.querySelectorAll("li")).map((li) => li.textContent);
const click = (name) => fireEvent.click(screen.getByRole("button", { name }));

test("[R1] shows only the first page of items initially", () => {
  render(<PaginatedList items={items(5)} pageSize={2} />);
  assert.deepEqual(shown(), ["Item 1", "Item 2"]);
});

test("[R2] Next shows the following page", () => {
  render(<PaginatedList items={items(5)} pageSize={2} />);
  click("Next");
  assert.deepEqual(shown(), ["Item 3", "Item 4"]);
});

test("[R3] Prev is disabled on the first page", () => {
  render(<PaginatedList items={items(5)} pageSize={2} />);
  assert.equal(screen.getByRole("button", { name: "Prev" }).disabled, true);
  assert.equal(screen.getByRole("button", { name: "Next" }).disabled, false);
});

test("[R4] shows 'Page X of Y'", () => {
  render(<PaginatedList items={items(5)} pageSize={2} />);
  assert.equal(screen.getByTestId("page-info").textContent, "Page 1 of 3");
});

