import { test, afterEach } from "node:test";
import assert from "node:assert/strict";
import { render, screen, fireEvent, cleanup } from "@testing-library/react";
import PaginatedList from "../../src/PaginatedList.jsx";

afterEach(cleanup);

const items = (n) => Array.from({ length: n }, (_, i) => `Item ${i + 1}`);
const shown = () => Array.from(document.querySelectorAll("li")).map((li) => li.textContent);
const click = (name) => fireEvent.click(screen.getByRole("button", { name }));

test("[R1] the last page holds the remainder", () => {
  render(<PaginatedList items={items(5)} pageSize={2} />);
  click("Next");
  click("Next");
  assert.deepEqual(shown(), ["Item 5"]);
});

test("[R1] pageSize defaults to 5", () => {
  render(<PaginatedList items={items(12)} />);
  assert.equal(shown().length, 5);
  assert.equal(screen.getByTestId("page-info").textContent, "Page 1 of 3");
});

test("[R2] Prev returns to the previous page", () => {
  render(<PaginatedList items={items(6)} pageSize={2} />);
  click("Next");
  click("Next");
  click("Prev");
  assert.deepEqual(shown(), ["Item 3", "Item 4"]);
});

test("[R3] Next is disabled on the last page, Prev enabled", () => {
  render(<PaginatedList items={items(4)} pageSize={2} />);
  click("Next");
  assert.equal(screen.getByRole("button", { name: "Next" }).disabled, true);
  assert.equal(screen.getByRole("button", { name: "Prev" }).disabled, false);
});

test("[R4] the indicator follows navigation", () => {
  render(<PaginatedList items={items(7)} pageSize={3} />);
  click("Next");
  assert.equal(screen.getByTestId("page-info").textContent, "Page 2 of 3");
});

test("[R5] an empty list shows the empty state and disables both buttons", () => {
  render(<PaginatedList items={[]} pageSize={3} />);
  assert.ok(screen.getByText("No items found"));
  assert.equal(document.querySelectorAll("ul").length, 0);
  assert.equal(screen.getByTestId("page-info").textContent, "Page 0 of 0");
  assert.equal(screen.getByRole("button", { name: "Prev" }).disabled, true);
  assert.equal(screen.getByRole("button", { name: "Next" }).disabled, true);
});

test("[R6] a shrinking list falls back to the last valid page", () => {
  const { rerender } = render(<PaginatedList items={items(9)} pageSize={3} />);
  click("Next");
  click("Next"); // page 3 of 3
  rerender(<PaginatedList items={items(4)} pageSize={3} />);
  assert.equal(screen.getByTestId("page-info").textContent, "Page 2 of 2");
  assert.deepEqual(shown(), ["Item 4"]);
});
